// =====================================================================
// EVERWAKE — Test Runner · NODE: Read Test Command
// Chat with a restaurant's agent as a pretend customer. The real Main
// workflow answers; nothing is sent on WhatsApp.
//
//   any text                 a customer message
//   /reset   (ريست)          forget the test chat: a brand-new customer
//   /last    (آخر)           show the latest turn again, sending nothing
//   /later 5 <message>       5 hours pass first (بعد 5 …), then the message
//   /pin 31.2,29.9 [text]    a location pin (لوكيشن), with or without text
//   #2 <message>             a second pretend customer (#1 … #99)
//   @gleem <message>         another restaurant, by its slug
// =====================================================================
const RESTAURANT = 'seagull';      // the slug (or English name) of the restaurant to test
const NAME = 'تجربة';              // the WhatsApp profile name the agent sees

let raw = String($input.first().json.chatInput ?? '').trim();
let restaurant = RESTAURANT, n = 1;
let m;
if ((m = raw.match(/^@(\S+)\s*([\s\S]*)$/))) { restaurant = m[1]; raw = m[2].trim(); }
if ((m = raw.match(/^#(\d{1,2})\s*([\s\S]*)$/))) { n = Math.min(Math.max(Number(m[1]), 1), 99); raw = m[2].trim(); }

const later = raw.match(/^\/(?:later|بعد)\s+(\d+(?:\.\d+)?)\s*([\s\S]*)$/i);
if (later) raw = later[2].trim();
const reset = /^\/?(reset|ريست)$/i.test(raw);
const last = /^\/(last|آخر)$/i.test(raw);
const pin = raw.match(/^\/(?:pin|لوكيشن)\s+(-?\d+(?:\.\d+)?)\s*[,،\s]\s*(-?\d+(?:\.\d+)?)\s*([\s\S]*)$/i);
const text = pin ? pin[3].trim() : (reset || last ? '' : raw);

return [{
  json: {
    restaurant,
    wa_id: '2000000000' + String(n).padStart(2, '0'),
    push_name: NAME + (n > 1 ? ' ' + n : ''),
    text,
    location: pin ? { lat: Number(pin[1]), lng: Number(pin[2]) } : null,
    reset,
    last,
    later_hours: later ? Number(later[1]) : 0,
    empty: !reset && !last && !text && !pin
  }
}];

// =====================================================================
// EVERWAKE — Test Runner · NODE: Fake WhatsApp Message
// The message as Evolution would deliver it, plus test_run: Main then
// records its replies instead of sending them.
// =====================================================================
const cmd = $('Read Test Command').first().json;
const r = $input.first().json.r;
const message = cmd.location
  ? { locationMessage: { degreesLatitude: cmd.location.lat, degreesLongitude: cmd.location.lng, name: cmd.text || undefined } }
  : { conversation: cmd.text };
return [{
  json: {
    test_run: true,
    query: { token: r.token },
    body: {
      event: 'messages.upsert',
      instance: r.instance,
      data: {
        key: { remoteJid: `${r.wa_id}@s.whatsapp.net`, fromMe: false, id: 'TESTIN' + Date.now() + Math.random().toString(36).slice(2, 8) },
        pushName: cmd.push_name,
        messageType: cmd.location ? 'locationMessage' : 'conversation',
        messageTimestamp: Math.floor(Date.now() / 1000),
        message
      }
    }
  }
}];

// =====================================================================
// EVERWAKE — Test Runner · NODE: Format Test Result
// What the chat (and whoever is testing) reads back: the reply exactly as
// the customer would get it, then what the agent did and why.
// =====================================================================
const cmd = $('Read Test Command').first().json;
const prep = $('Prepare Test Chat').first().json.r || {};
const res = ($input.first().json.r) || {};
const short = (v, n = 600) => { const s = typeof v === 'string' ? v : JSON.stringify(v); return !s ? '' : s.length > n ? s.slice(0, n - 1) + '…' : s; };

if (cmd.empty) return [{ json: { output: 'Type a customer message, or /reset, /last, /later 5 <message>, /pin <lat>,<lng>.' } }];
if (prep.reset) return [{ json: { output: `RESET — ${prep.restaurant}: the test chat ${prep.wa_id} starts from zero (a brand-new customer).` } }];

let route = null;
try { route = $('Run The Agent (Main)').first().json?.r?.route || null; } catch (e) { /* not run */ }
const replies = Array.isArray(res.replies) ? res.replies : [];
const said = replies.map(m => m.kind === 'text' ? m.text : `[${m.kind}] ${m.text || ''}`).join('\n[[NEXT]]\n');
const t = res.turn || {};
const b = t.plan && typeof t.plan === 'object' ? t.plan : null;
const plan = !b ? null : b.used ? `${b.stage} — ${b.objective}${b.place_order ? ' · PLACE' : ''}${b.show_summary ? ' · SUMMARY' : ''}` : `(no plan: ${b.error})`;

const lines = [
  `${cmd.last ? '(the latest turn again) ' : ''}${prep.later_hours ? `(${prep.later_hours} hours later) ` : ''}CUSTOMER: ${res.customer ?? cmd.text}`,
  `AGENT: ${said || `(no reply — ${route && route !== 'agent' ? 'route ' + route : 'see the Main execution'})`}`,
  '',
  `${prep.restaurant} · ${prep.status}${res.mode === 'human' ? ' · A PERSON TOOK OVER' : ''} · stage=${t.stage ?? '-'} · ${t.seconds ?? '-'}s · ${t.tokens ?? '-'} tokens`,
  ...((t.calls || []).length
    ? t.calls.map(c => `→ ${c.tool} ${short(c.asked, 220)} ⇒ ${c.status || '?'}${c.error ? ' «' + c.error + '»' : ''}${(c.problems || []).length ? ' ' + c.problems.join(',') : ''}`)
    : [`tools=${short(t.tools || [])}`]),
  (t.tool_problems || []).length ? `problems=${short(t.tool_problems, 400)}` : '',
  t.agent_error ? `AGENT ERROR: ${t.agent_error}` : '',
  (t.caught || []).length ? `caught=${short(t.caught, 800)}${t.rewritten ? ' → rewritten' : ''}` : 'caught=none',
  `plan=${plan ?? '(none)'}`,
  `branch=${res.branch ?? '-'} · cart=${short(res.cart || [])}`,
  `details=${short(res.details || {}, 500)}`,
  res.orders ? `orders=${short(res.orders)}` : '',
  t.order_placed ? `ORDER PLACED ${t.order_placed} (no ticket sent to the kitchen in a test)` : '',
  t.handoff && t.handoff.needed ? `HANDOFF: ${t.handoff.reason}` : ''
].filter(l => l !== '');
return [{ json: { output: lines.join('\n'), reply: said || null } }];
